void Solver::rephase() {
    rephases = 0;
    // Cycle through different rephasing strategies based on rephase_limit
    int strategy = (rephase_limit / 8192) % 4;
    if (strategy == 0) {
        // Use local best phase (most common - exploit best found assignment)
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else if (strategy == 1) {
        // Use inverted local best phase (explore opposite polarity)
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else if (strategy == 2) {
        // Random phase assignment (diversification)
        for (int i = 1; i <= vars; i++) saved[i] = rand() % 2 ? 1 : -1;
    } else {
        // All positive phase (unit propagation friendly)
        for (int i = 1; i <= vars; i++) saved[i] = 1;
    }
    threshold *= 0.9;
    rephase_limit += 8192;
}
// end
